fn image(path:&Path,raw:&[u8],format:Format)->anyhow::Result<()>{let mut rgba=Vec::new();let shifts=if format==Format::Rgb555{[10,5,0]}else{[11,5,0]};let bits=if format==Format::Rgb555{[5,5,5]}else{[5,6,5]};for p in raw.chunks_exact(2){let w=u16::from_le_bytes([p[0],p[1]]);for(s,b)in shifts.into_iter().zip(bits){let n=((w>>s)&((1u16<<b)-1))as u8;rgba.push((n<<(8-b))|(n>>(2*b-8)));}rgba.push(255);}let mut e=png::Encoder::new(fs::File::create(path)?,640,480);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header()?.write_image_data(&rgba)?;Ok(())}
